sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    const elementId = event.elementId;
    let riskEventToBeAssociated = "";
    let riskEventNumber = '';
    let isExpanded = false;
    if (elementId == 'associate_risk_event_details'){
        riskEventToBeAssociated = api.state.expandedInfo.expandedItem.sysId;
        riskEventNumber = api.state.expandedInfo.expandedItem.number;
        isExpanded = true;
    }else{
        riskEventToBeAssociated = event.context.item.value.sysId;
        riskEventNumber = event.context.item.value.number;
    }

    api.emit("NOW_UXF_PAGE#SET_LOADING_STATE", {
        id: "non_blocking",
        loading: true,
        nonBlocking: true
    });

    helpers.snHttp('/api/sn_grc_pred_intel/risk_event_api/associate', {
        method: "POST",
        body: {
            parentRiskEventId: api.context.props.sysId,
            riskEventToBeAssociated
        },
        batch: false

    }).then(async({
        response
    }) => {
        api.data.get_similar_risk_events.refresh();
        if(isExpanded)
            api.setState('hideAssociateButton', true);
        var notificationData = {};
        var result = response.result;
        if (result && result.isError) {
            notificationData.icon = 'error-circle-outline';
            notificationData.status = 'error';
            notificationData.message = result.message;
        } else {
            notificationData.icon = 'circle-check-outline';
            notificationData.status = 'positive';
            const link = `<a href="/now/risk/page/record/sn_risk_advanced_event/${riskEventToBeAssociated}" target="_blank"> ${riskEventNumber} </a>`;
            const message = await helpers.translate('The risk event {0} is successfully associated.', [link]);
            notificationData.message = {
                    type: 'html',
                    value: `<div>
                                ${message}
                            </div>`
            };
        }

        api.emit("RECORD#RELATED_LIST_REFRESH_REQUESTED", {
            relatedListName: "sn_risk_advanced_m2m_event_event.risk_event"
        });

        api.emit('NOW_UXF_PAGE#ADD_NOTIFICATIONS', {
            items: [{
                id: 'risk_event_association',
                status: notificationData.status,
                icon: notificationData.icon,
                content: notificationData.message,
                action: {
                    type: "dismiss"
                }
            }]
        });

        api.emit("NOW_UXF_PAGE#SET_LOADING_STATE", {
            id: "non_blocking",
            loading: false,
            nonBlocking: true
        });
    });
}
